            satMod += (amzp_satHighlights / 100.0) * zHighs;
            satMod += (amzp_satWhites / 100.0) * zWhites;
            satMod = max(satMod, 0.0);
            rgb = mix(float3(l), rgb, satMod);
        }
        float zl = lum(rgb);
