        if (amzp_midtoneTintStr > 0.00001) {
            float midMask = smoothstep(0.0, 0.3, zl) * smoothstep(1.0, 0.7, zl);
            float3 midTint = (amzp_midtoneTint.rgb - 0.5) * 2.0;
            float origLum = lum(rgb);
            rgb += midTint * amzp_midtoneTintStr * midMask * 0.2;
            float newLum = lum(rgb);
